import { safeExternalUrl } from './url-domain';
import { decodeItem } from './item-domain';
import type { HelpersBridge, SharedCore, SharedClient } from './host';
export function createHelpers(JE: HelpersBridge, api: () => SharedClient) {


    // Tracks whether the MUI-toolbar button-sizing CSS fix has been injected (see
    // getHeaderRightContainer below) so it's only added once.
    let muiHeaderButtonCSSInjected = false;

    // Containers with the mobile-drawer-auto-close listener already attached.
    const drawerAutoCloseContainers = new WeakSet<Element>();

    /**
     * Closes jellyfin-web's mobile nav drawer (SwipeableDrawer) if open, so
     * tapping a header icon doesn't leave it open behind the action. Scoped
     * below the `md` (900px) breakpoint since `.MuiDrawer-paper` at/above it
     * belongs to the unrelated permanent sidebar drawer.
     */
    function closeMobileDrawerIfOpen() {
        if (window.matchMedia('(min-width: 900px)').matches) return;
        const paper = document.querySelector('.MuiDrawer-paper');
        if (!paper) return;
        // A kept-mounted drawer can retain a positive right edge while hidden.
        // Check visibility as well as position before toggling its backdrop.
        if (getComputedStyle(paper).visibility === 'hidden' ||
            paper.closest('.MuiModal-hidden') || paper.getBoundingClientRect().right <= 0) return;
        // onOpen/onClose both just flip one boolean, so clicking the
        // backdrop (what a real outside click does) toggles it closed --
        // only safe because we've confirmed it's open above.
        paper.closest('.MuiModal-root')?.querySelector<HTMLElement>(':scope > .MuiBackdrop-root')?.click();
    }

    /**
     * Wires closeMobileDrawerIfOpen() into a header-icon container via a
     * capturing listener, so any button inside it closes the drawer first.
     * @param {HTMLElement|null} container
     */
    function attachDrawerAutoClose(container: Element | null) {
        if (!container || drawerAutoCloseContainers.has(container)) return;
        drawerAutoCloseContainers.add(container);
        container.addEventListener('click', (event) => {
            // Launcher actions close their dialog before forwarding the action.
            // Do not toggle an unrelated drawer while forwarding that click.
            if (!(event.target instanceof Element && event.target.closest('.je-header-overflowed'))) closeMobileDrawerIfOpen();
        }, true);
    }

    // ── Admin check ──────────────────────────────────────────────────────────
    // Single source of truth for "is the current user an administrator?".
    // Sourced from JE.currentSettings.isAdmin, which the server computes fresh
    // from the authenticated caller on every settings.json GET and never
    // persists to the file (see GetUserSettingsSettings in
    // Features/Settings/JeSettingsController.cs). This is a UX gate only: every admin-only
    // endpoint enforces access independently server-side.
    /**
     * @returns {boolean}
     */
    function isAdmin() {
        return JE.currentSettings?.isAdmin === true;
    }

    // Shared cache for item payloads to deduplicate cross-module api().getItem calls
    const itemCache = new Map<string, { item: Record<string, unknown> | null; ts: number; promise: Promise<Record<string, unknown> | null> | null }>();
    let generation = 0;
    let scope = '';
    function identity() {
        const host = api();
        return JSON.stringify([host.getCurrentUserId(), typeof host.serverId === 'function' ? host.serverId() : host.serverId, host.accessToken?.()]);
    }
    function invalidate() { generation++; itemCache.clear(); clearAvatarObjectUrlCache(true); }
    function lease() {
        const current = identity();
        if (scope !== current) { scope = current; invalidate(); }
        JE.session?.checkNow?.('shared-helpers');
        const session = JE.session?.createLease?.();
        const captured = generation;
        return () => captured === generation && current === identity() && (!session || session.isCurrent());
    }
    const ITEM_CACHE_TTL_MS = 30000; // 30s -- long enough for batch prefetch to warm cache before tag systems scan

    // Protected Seerr avatars require authenticated blob fetches because a
    // plain <img> cannot attach Jellyfin auth headers. Keep one shared cache
    // for the Requests page and Seerr More Info modal.
    let avatarGeneration = 0;
    const avatarObjectUrlCache = new Map<string, string>();
    const avatarFetchPromises = new Map<string, Promise<string>>();

    function getAvatarAuthHeaders() {
        const token = api().accessToken?.() || '';
        return {
            'Authorization': 'MediaBrowser Token="' + token + '"',
            'X-MediaBrowser-Token': token,
        };
    }

    function isSafeAvatarUrl(url: unknown): url is string {
        if (!url || typeof url !== 'string') return false;
        if (url.startsWith('/') || url.startsWith('blob:')) return true;

        try {
            const parsed = new URL(url, window.location.origin);
            if (parsed.protocol === 'http:' || parsed.protocol === 'https:') return true;
            if (parsed.protocol === 'data:') return /^data:image\//i.test(url);
        } catch {
            return false;
        }
        return false;
    }

    async function resolveProtectedAvatarUrl(avatarUrl: string): Promise<string> {
        const current = lease();
        const avatarEpoch = avatarGeneration;
        if (!isSafeAvatarUrl(avatarUrl)) return '';
        if (!avatarUrl.startsWith('/JellyfinEnhanced/proxy/avatar')) return avatarUrl;
        if (avatarObjectUrlCache.has(avatarUrl)) return avatarObjectUrlCache.get(avatarUrl) || '';
        if (avatarFetchPromises.has(avatarUrl)) return avatarFetchPromises.get(avatarUrl) || '';

        const fetchPromise = Promise.resolve().then(async () => {
            try {
                const response = await fetch(api().getUrl(avatarUrl), { headers: getAvatarAuthHeaders() });
                if (!response.ok) return '';
                const blob = await response.blob();
                if (!current() || avatarEpoch !== avatarGeneration) return '';
                const objectUrl = URL.createObjectURL(blob);
                avatarObjectUrlCache.set(avatarUrl, objectUrl);
                return objectUrl;
            } catch {
                return '';
            } finally {
                if (avatarFetchPromises.get(avatarUrl) === fetchPromise) avatarFetchPromises.delete(avatarUrl);
            }
        });

        avatarFetchPromises.set(avatarUrl, fetchPromise);
        return fetchPromise;
    }

    function hydrateAvatarImages(container: ParentNode) {
        const avatarImgs = container.querySelectorAll<HTMLImageElement>('img.je-request-avatar[data-avatar-src]');
        avatarImgs.forEach(async (img) => {
            const sourceUrl = img.getAttribute('data-avatar-src');
            if (!sourceUrl) {
                img.style.display = 'none';
                return;
            }

            const current = lease();
            const avatarEpoch = avatarGeneration;
            const resolvedUrl = await resolveProtectedAvatarUrl(sourceUrl);
            if (!current() || avatarEpoch !== avatarGeneration || !img.isConnected || img.getAttribute('data-avatar-src') !== sourceUrl) return;
            if (!resolvedUrl || !isSafeAvatarUrl(resolvedUrl)) {
                img.style.display = 'none';
                return;
            }

            img.src = resolvedUrl;
            img.style.display = '';
        });
    }

    function clearAvatarObjectUrlCache(includeInFlight = false) {
        // Ordinary rerenders can join the same still-valid download. Explicit
        // invalidation retires both the pending promise and its UI continuations.
        if (includeInFlight) {
            avatarGeneration++;
            avatarFetchPromises.clear();
        }
        avatarObjectUrlCache.forEach((objectUrl) => URL.revokeObjectURL(objectUrl));
        avatarObjectUrlCache.clear();
    }

    // Item lookups are keyed `${userId}:${itemId}` so they can't collide
    // across users, but flush anyway on a switch (frees memory and drops
    // entries fetched with a token that is about to be revoked). Avatars are
    // the Seerr-linked user's own.
    JE.session?.onUserChange('helpers', invalidate);
    window.addEventListener('beforeunload', invalidate);

    /**
     * Deduplicated item fetch with short TTL cache, dropped when Spoiler Guard changes
     * because the server's item fields depend on it.
     * Prevents multiple modules from requesting the same item concurrently on detail page navigation.
     * @param {string} itemId
     * @param {Object} [options]
     * @param {string} [options.userId]
     * @param {number} [options.ttlMs]
     * @param {boolean} [options.forceRefresh]
     * @returns {Promise<object|null>}
     */
    window.addEventListener('je:spoiler-state-changed', () => { generation++; itemCache.clear(); });

    async function getItemCached(itemId: string, options: {userId?: string; ttlMs?: number; forceRefresh?: boolean} = {}) {
        if (!itemId) return null;
        const current = lease();

        const ttlMs = typeof options.ttlMs === 'number' && Number.isFinite(options.ttlMs) ? options.ttlMs : ITEM_CACHE_TTL_MS;
        const userId = options.userId || api().getCurrentUserId();
        const key = JSON.stringify([scope, userId, itemId]);
        const now = Date.now();
        const entry = itemCache.get(key);

        if (!options.forceRefresh && entry) {
            if (entry.promise) {
                return entry.promise;
            }
            if (entry.item && (now - entry.ts) < ttlMs) {
                return entry.item;
            }
        }

        // Only the entry this request registered may be filled: a clear since then means
        // the answer is from before a guard or user change.
        const promise = api().getItem(userId, itemId)
            .then((value: unknown) => {
                if (!current()) return null;
                const item = decodeItem(value);
                if (itemCache.get(key)?.promise === promise) {
                    itemCache.set(key, { item, ts: Date.now(), promise: null });
                }
                return item;
            })
            .catch((err) => {
                if (itemCache.get(key)?.promise === promise) itemCache.delete(key);
                throw err;
            });

        itemCache.set(key, { item: null, ts: now, promise });
        return promise;
    }


    /**
     * Debounce a function call
     * @param {Function} func - The function to debounce
     * @param {number} wait - Wait time in ms
     * @param {{maxWait?: number}} [options] - maxWait caps how long a burst of
     *   calls can keep postponing the call (ms since the burst's first call).
     * @returns {Function}
     */
    function debounce<A extends unknown[]>(func: (...args: A) => void, wait: number, options?: {maxWait?: number}) {
        const maxWait = options?.maxWait !== undefined && options.maxWait > 0 ? options.maxWait : Infinity;
        // Trailing-edge debounce that keeps one timer alive per burst instead of
        // clearing and re-arming a timer on every call: the observer-driven
        // callers are invoked hundreds of times per navigation, and the
        // clear+set pair each time was the plugin's single largest source of
        // timers (~6,300 per ten navigations). The timer re-checks the last call
        // time when it fires and re-arms only for the remaining wait.
        let timeout: ReturnType<typeof setTimeout> | null = null;
        let lastCall = 0;
        let firstCall = 0;
        let lastArgs: A;
        const fire = () => {
            const now = Date.now();
            const remaining = Math.min(wait - (now - lastCall), maxWait - (now - firstCall));
            if (remaining > 0) {
                timeout = setTimeout(fire, remaining);
                return;
            }
            timeout = null;
            func(...lastArgs);
        };
        return function executedFunction(...args: A) {
            lastArgs = args;
            lastCall = Date.now();
            if (timeout === null) {
                firstCall = lastCall;
                timeout = setTimeout(fire, Math.min(wait, maxWait));
            }
        };
    }

    /**
     * Throttle a function call
     * @param {Function} func - The function to throttle
     * @param {number} limit - Time limit in ms
     * @returns {Function}
     */
    function throttle<A extends unknown[], T>(func: (this: T, ...args: A) => void, limit: number) {
        let inThrottle = false;
        return function(this: T, ...args: A) {
            if (!inThrottle) {
                func.apply(this, args);
                inThrottle = true;
                setTimeout(() => inThrottle = false, limit);
            }
        };
    }

    /**
     * Retry a function with exponential backoff
     * @param {Function} fn - The async function to retry
     * @param {number} maxAttempts - Maximum retry attempts (default: 5)
     * @param {number} baseDelay - Base delay in ms (default: 1000)
     * @returns {Promise<any>}
     */
    async function retry<T>(fn: () => Promise<T>, maxAttempts = 5, baseDelay = 1000) {
        let lastError;

        for (let attempt = 1; attempt <= maxAttempts; attempt++) {
            try {
                return await fn();
            } catch (error) {
                lastError = error;

                if (attempt === maxAttempts) {
                    console.error(`🪼 Jellyfin Enhanced: Failed after ${maxAttempts} attempts:`, error);
                    throw error;
                }

                const delay = baseDelay * Math.pow(2, attempt - 1);
                console.warn(`🪼 Jellyfin Enhanced: Attempt ${attempt}/${maxAttempts} failed, retrying in ${delay}ms...`, error);
                await new Promise(resolve => setTimeout(resolve, delay));
            }
        }

        throw lastError;
    }

    /**
     * Check if an element is visible in the viewport
     * @param {HTMLElement} element - The element to check
     * @returns {boolean}
     */
    function isElementVisible(element: Element | null) {
        if (!element) return false;

        const rect = element.getBoundingClientRect();
        return (
            rect.top >= 0 &&
            rect.left >= 0 &&
            rect.bottom <= (window.innerHeight || document.documentElement.clientHeight) &&
            rect.right <= (window.innerWidth || document.documentElement.clientWidth)
        );
    }

    /**
     * Finds (or creates) the container plugin buttons should be injected into.
     *
     * Jellyfin 12's "experimental" layout (now the default) replaces the legacy
     * AngularJS header with a React/MUI AppBar+Toolbar. The legacy `.headerRight`
     * element is still present in the DOM for backwards compatibility, but it sits
     * inside a `display:none` wrapper, so injecting into it silently produces
     * invisible buttons. When that's detected, this reuses the toolbar's own
     * SyncPlay/RemotePlay/Search button tray (a `flexGrow:1; justifyContent:flex-end`
     * Box) as the container — it's the functional equivalent of `.headerRight`, and
     * injecting into it (rather than next to it) keeps plugin buttons right-aligned
     * with the native ones instead of stranding them as a separate flex item further
     * left in the toolbar.
     * @returns {HTMLElement|null} The container, or null if no header is ready yet.
     */
    function getHeaderRightContainer() {
        const legacy = document.querySelector<HTMLElement>('.headerRight:not([data-je-header-fallback])');
        if (legacy && legacy.offsetParent !== null) {
            attachDrawerAutoClose(legacy);
            return legacy;
        }

        const userMenuButton = document.querySelector<HTMLElement>('[aria-controls="app-user-menu"]');
        const toolbar = userMenuButton?.closest('.MuiToolbar-root') || document.querySelector('.MuiAppBar-root .MuiToolbar-root');
        if (!toolbar) return null;

        // The legacy .headerButton/.paper-icon-button-light classes size themselves
        // with `em` units relative to the *inherited* font-size, which was tuned for
        // the old .skinHeader context. Inside the MUI toolbar the ambient font-size is
        // different, so the icons come out oversized/misaligned next to the native MUI
        // IconButtons. Pin them to MUI's own ~48px button / 24px icon convention instead.
        // !important is needed because some callers (e.g. active-streams.js) set their
        // own fixed-size CSS via an #id selector, which otherwise outranks this rule's
        // specificity regardless of declaration order.
        if (!muiHeaderButtonCSSInjected || !document.getElementById('je-mui-header-button-fix')) {
            addCSS('je-mui-header-button-fix', `
                .MuiToolbar-root .headerButton.paper-icon-button-light {
                    display: inline-flex !important;
                    align-items: center !important;
                    justify-content: center !important;
                    box-sizing: border-box !important;
                    width: 48px !important;
                    height: 48px !important;
                    padding: 0 !important;
                    margin: 0 !important;
                    font-size: 16px !important;
                }
                .MuiToolbar-root .headerButton.paper-icon-button-light > .material-icons {
                    font-size: 24px !important;
                }
            `);
            muiHeaderButtonCSSInjected = true;
        }

        let userMenuBox: Element | null = userMenuButton;
        while (userMenuBox && userMenuBox.parentElement !== toolbar) {
            userMenuBox = userMenuBox.parentElement;
        }
        let buttonsTray = userMenuBox?.previousElementSibling;
        // Found mid-render (user menu not mounted yet), our fallback container ends up
        // between the native tray and the user menu. Look past it once the tray exists.
        if (buttonsTray?.hasAttribute('data-je-header-fallback') && buttonsTray.previousElementSibling?.matches('.MuiBox-root')) {
            buttonsTray = buttonsTray.previousElementSibling;
        }
        // Other plugins (e.g. Moonfin) can put their own button here; never host inside one.
        const isInteractive = buttonsTray?.matches('button, a, [role="button"]');
        if (buttonsTray && !isInteractive) {
            attachDrawerAutoClose(buttonsTray);
            return buttonsTray;
        }

        // Fallback: a container we own (foreign button before the user menu, or no user menu).
        let container = toolbar.querySelector<HTMLElement>(':scope > .headerRight');
        if (!container) {
            container = document.createElement('div');
            container.className = 'headerRight';
            container.dataset.jeHeaderFallback = '';
            if (userMenuBox) toolbar.insertBefore(container, userMenuBox);
            else toolbar.appendChild(container);
        } else if (userMenuBox && container.nextElementSibling !== userMenuBox && container.compareDocumentPosition(userMenuBox) & Node.DOCUMENT_POSITION_PRECEDING) {
            toolbar.insertBefore(container, userMenuBox);
        }
        attachDrawerAutoClose(container);
        return container;
    }

    /** Return the shared adaptive JE header actions tray. */
    function getHeaderButtonTray() {
        return JE.headerActions?.getTray() || null;
    }

    /**
     * Finds the container plugin sidebar nav links should be injected into.
     *
     * The legacy `.mainDrawer-scrollContainer` is hidden the same way `.headerRight`
     * is under Jellyfin 12's experimental layout (both live inside the
     * `display:none`-wrapped legacy AppHeader). Unlike the header, there's no
     * always-present replacement: the new drawer (`AppDrawer`/`MainDrawerContent`,
     * a MUI `SwipeableDrawer`) is itself only ever rendered at all on narrow/mobile
     * viewports - desktop has no drawer in the new layout at all, nav lives inline
     * in the toolbar instead (see getHeaderRightContainer). So on desktop there is
     * no sidebar equivalent to fall back to; this returns null there, same as if
     * nothing existed yet, and callers' existing "wait and retry" logic covers it.
     * @returns {HTMLElement|null}
     */
    function getSidebarContainer() {
        const legacy = document.querySelector<HTMLElement>('.mainDrawer-scrollContainer');
        if (legacy && legacy.offsetParent !== null) return legacy;

        // The dashboard/settings pages render their own MUI drawer (admin nav),
        // which also matches `.MuiDrawer-paper` - there's nothing in the class
        // name that distinguishes it from the home/library drawer. Plugin nav
        // links belong in the home sidebar only, so bail out here rather than
        // injecting into the admin drawer.
        if (document.body.classList.contains('dashboardDocument')) {
            return null;
        }

        // MUI's global stable class for the drawer's sliding panel. `keepMounted`
        // on the SwipeableDrawer means this exists in the DOM even while closed.
        const muiDrawerPanel = document.querySelector('.MuiDrawer-paper');
        if (!muiDrawerPanel) return null;

        return muiDrawerPanel.querySelector('[role="presentation"]') || muiDrawerPanel;
    }

    // --- Shared sidebar re-injection watcher ---
    // Every sidebar page (bookmarks, hidden content, requests, calendar,
    // recommendations) used to run its own document-wide MutationObserver to
    // put its nav link back when Jellyfin rebuilds the drawer. Five observers,
    // each querying the document on every DOM change, cost ~250 ms per ten
    // navigations. One subscription on the shared (post-paint, batched) body
    // observer now checks `isConnected` on the cached elements instead, and
    // only calls a page's injector when its link is gone and the section exists.
    /** @type {Map<string, { selector: string, inject: Function, element: Element|null }>} */
    const sidebarNavEntries = new Map<string, {selector: string; inject: () => void; element: Element | null}>();
    /** @type {Element|null} */
    let sidebarSectionElement: Element | null = null;
    let sidebarNavSubscribed = false;
    let sidebarUnsubscribe: (() => void) | undefined;

    function checkSidebarNavEntries() {
        if (sidebarNavEntries.size === 0) return;
        if (!sidebarSectionElement || !sidebarSectionElement.isConnected) {
            sidebarSectionElement = document.querySelector('.jellyfinEnhancedSection');
            if (!sidebarSectionElement) return;
        }
        for (const entry of sidebarNavEntries.values()) {
            if (entry.element && entry.element.isConnected) continue;
            entry.element = document.querySelector(entry.selector);
            if (entry.element) continue;
            try {
                entry.inject();
            } catch (err) {
                console.error('🪼 Jellyfin Enhanced: Sidebar nav injector failed:', err);
            }
            entry.element = document.querySelector(entry.selector);
        }
    }

    /**
     * Re-run `inject` whenever the sidebar is rebuilt without this page's nav
     * link. `inject` keeps its own gating (config mode checks) and must be
     * idempotent; it runs only when `.jellyfinEnhancedSection` exists and no
     * element matches `selector`.
     * @param {string} id - Unique id per page (replaces an earlier registration).
     * @param {string} selector - Selector matching the page's injected nav link.
     * @param {Function} inject - Injects the nav link into the section.
     * @returns {Function} Unregister function.
     */
    function onSidebarRebuilt(id: string, selector: string, inject: () => void) {
        const entry = { selector, inject, element: null };
        sidebarNavEntries.set(id, entry);
        if (!sidebarNavSubscribed) {
            sidebarNavSubscribed = true;
            const subscription = JE.core.dom.onBodyMutation('sidebar-nav-watcher', checkSidebarNavEntries);
            sidebarUnsubscribe = () => subscription.unsubscribe();
        }
        return () => {
            if (sidebarNavEntries.get(id) !== entry) return;
            sidebarNavEntries.delete(id);
            if (!sidebarNavEntries.size) { sidebarUnsubscribe?.(); sidebarNavSubscribed = false; sidebarSectionElement = null; }
        };
    }

    /** @param {Element} element @returns {Element[]} All page/tab ancestors, innermost first. */
    function getTabAncestors(element: Element) {
        const ancestors = [];
        for (let node: Element | null = element; node; node = node.parentElement) {
            if (node.matches('.page, .tabContent')) ancestors.push(node);
        }
        return ancestors;
    }

    /**
     * A visible page can contain inactive or nested tabs. A placeholder itself
     * may be hidden until its renderer reveals it; only its page/tab wrappers
     * determine whether it should mount.
     * @param {Element} element - The feature's content placeholder.
     * @returns {boolean} Whether every enclosing page/tab is active.
     */
    function isActiveTabContainer(element: HTMLElement) {
        if (!element.isConnected) return false;
        const ancestors = getTabAncestors(element);
        for (const ancestor of ancestors) {
            if ((ancestor instanceof HTMLElement && ancestor.hidden) || ancestor.classList.contains('hide')) return false;
            if (ancestor.classList.contains('tabContent') && !ancestor.classList.contains('is-active')) return false;
        }
        return ancestors.length > 0 || element.offsetParent !== null;
    }

    /**
     * Watch mounts and class-only activation without observing attributes on
     * the whole document. The background-tab fallback also lets pollers stop
     * when animation frames are suspended. The returned handle owns cleanup.
     * @param {string} id - Unique lifecycle/subscriber ID.
     * @param {string} selector - Selector for this feature's placeholders.
     * @param {Function} callback - Reconcile the currently active placeholder.
     * @returns {object} Lifecycle handle with teardown().
     */
    function observeTabContainers(id: string, selector: string, callback: () => void) {
        const lifecycle = JE.core.lifecycle.register(id);
        lifecycle.teardown();
        let pending = false;
        let disposed = false;
        const observed = new Set<Element>();
        const flush = () => {
            if (disposed || !pending) return;
            pending = false;
            const ancestors = new Set<Element>();
            document.querySelectorAll(selector).forEach(element => {
                getTabAncestors(element).forEach(ancestor => ancestors.add(ancestor));
            });
            if (ancestors.size !== observed.size || [...ancestors].some(el => !observed.has(el))) {
                observer.disconnect();
                observed.clear();
                ancestors.forEach(el => {
                    observer.observe(el, { attributes: true, attributeFilter: ['class', 'hidden'] });
                    observed.add(el);
                });
            }
            callback();
        };
        const schedule = () => {
            if (pending || disposed) return;
            pending = true;
            JE.core.dom.afterNextPaint(flush);
        };
        const observer = lifecycle.track(new MutationObserver(schedule));
        lifecycle.track(JE.core.dom.onBodyMutation(id, schedule));
        lifecycle.track(JE.core.navigation.onNavigate(schedule));
        lifecycle.track(() => {
            disposed = true;
            pending = false;
        });
        schedule();
        return lifecycle;
    }

    /**
     * Wait for a condition to be true
     * @param {Function} condition - Function that returns boolean
     * @param {number} timeout - Maximum wait time in ms (default: 5000)
     * @param {number} interval - Check interval in ms (default: 100)
     * @returns {Promise<boolean>}
     */
    function waitForCondition(condition: () => boolean, timeout = 5000, interval = 100) {
        return new Promise((resolve) => {
            const startTime = Date.now();

            const checkCondition = () => {
                if (condition()) {
                    resolve(true);
                    return;
                }

                if (Date.now() - startTime >= timeout) {
                    console.warn('🪼 Jellyfin Enhanced: Timeout waiting for condition');
                    resolve(false);
                    return;
                }

                setTimeout(checkCondition, interval);
            };

            checkCondition();
        });
    }

    /**
     * Add custom CSS to the page (alias of JE.core.ui.injectCss).
     * @param {string} id - Unique ID for the style element
     * @param {string} css - The CSS content
     */
    function addCSS(id: string, css: string) {
        JE.core.ui.injectCss(id, css);
    }

    /**
     * Creates an external-link <a> that Jellyfin's native apps open in the system
     * browser (iOS SFSafariViewController, Android Custom Tabs) via `is="emby-linkbutton"`.
     *
     * Use this for every external URL in the plugin — one place, consistent behaviour.
     *
     * @param {string} url
     * @param {object} [options]
     * @param {string}   [options.text]       - Text content.
     * @param {string}   [options.title]      - Tooltip.
     * @param {string}   [options.className]  - CSS class(es).
     * @param {boolean}  [options.resetStyle] - Strip emby-button chrome for plain-link appearance.
     * @param {Function} [options.setup]      - Callback(el) for extra DOM work.
     * @returns {HTMLAnchorElement}
     */
    function createExternalLink(url: string, options: {text?: string; title?: string; className?: string; resetStyle?: boolean; setup?: (el: HTMLAnchorElement) => void} = {}) {
        const a = document.createElement('a');
        // This attribute is what tells Jellyfin's native app shell to open the URL
        // in the system browser instead of the in-app WebView.
        a.setAttribute('is', 'emby-linkbutton');
        a.href = safeExternalUrl(url, window.location.href);
        a.target = '_blank';
        a.rel = 'noopener noreferrer';
        if (options.title)     a.title = options.title;
        if (options.className) a.className = options.className;
        if (options.text)      a.textContent = options.text;
        if (options.resetStyle) {
            // Strip the default emby-button chrome (padding, background, border-radius)
            // so the element renders as a plain unstyled link.
            a.style.cssText = 'padding:0;background:none;border-radius:0;min-width:0;';
        }
        if (typeof options.setup === 'function') options.setup(a);
        return a;
    }

    // Icon-only buttons we inject into .itemExternalLinks (Letterboxd, Seerr,
    // Radarr/Sonarr/Bazarr) need to match the height of Jellyfin's native
    // text-only IMDb/TMDB/Trakt buttons there — a fixed px/em guess only fits
    // one theme, so measure the real native button instead. Reads rendered
    // box height, not font-size/line-height: some themes give these buttons
    // an explicit height while zeroing out font-size/color on the label
    // itself (rendering it some other way), which would read as 0.
    const ownExternalLinkClasses = ['letterboxd-link', 'seerr-link', 'arr-link', 'arr-tag-link'];

    /**
     * Px content height Jellyfin's native external-link buttons (IMDb/TMDB/Trakt)
     * currently render at, so icon-only buttons in the same row can match it.
     * @param {number} [fallback=18] - px to use if no native button is found yet.
     * @returns {number}
     */
    function getExternalLinkIconSize(fallback = 18) {
        const container = document.querySelector('#itemDetailPage:not(.hide) .itemExternalLinks');
        if (!container) return fallback;
        const native = [...container.querySelectorAll('a')].find(a =>
            !ownExternalLinkClasses.some(cls => a.classList.contains(cls))
        );
        if (!native) return fallback;
        const rect = native.getBoundingClientRect();
        const cs = getComputedStyle(native);
        const verticalChrome = parseFloat(cs.paddingTop) + parseFloat(cs.paddingBottom)
            + parseFloat(cs.borderTopWidth) + parseFloat(cs.borderBottomWidth);
        const contentHeight = rect.height - (Number.isFinite(verticalChrome) ? verticalChrome : 0);
        return Number.isFinite(contentHeight) && contentHeight > 0 ? contentHeight : fallback;
    }

    /**
     * The Jellyfin header currently on screen: the legacy .skinHeader, or the
     * MUI app bar on Jellyfin 12 (where .skinHeader is hidden, zero height).
     * Its height varies by layout and theme, so measure it rather than assume.
     * @returns {HTMLElement|null}
     */
    function getHeaderElement() {
        for (const selector of ['.skinHeader', '.MuiAppBar-root']) {
            const el = document.querySelector(selector);
            if (el && el.getBoundingClientRect().height > 0 && getComputedStyle(el).visibility !== 'hidden') return el;
        }
        return null;
    }

    /**
     * Distance in px from the viewport top to the bottom of the Jellyfin
     * header, i.e. where fixed or sticky UI should start. 0 if none is showing.
     * @returns {number}
     */
    function getHeaderBottom() {
        const header = getHeaderElement();
        return header ? Math.round(header.getBoundingClientRect().bottom) : 0;
    }

    /**
     * Bumps one opt-in usage-analytics counter (e.g. "seerr.request_submitted").
     * Fire-and-forget: no-ops client-side when analytics/usage-counts aren't
     * both enabled (avoiding a pointless network call from the majority of
     * installs, which have this off by default), and the server independently
     * no-ops the same way, so this is always safe to call unconditionally
     * from any feature module without checking config first.
     * @param {string} key - feature_key, e.g. "seerr.request_submitted".
     *   Server-side validated as ^[a-z0-9_.]{1,64}$ AND against the allowlist
     *   in UsageEventCounterService.KnownKeys -- a new key must be added there
     *   in the same change that starts emitting it, or the endpoint rejects it.
     */
    function trackUsage(key: string) {
        try {
            if (!JE.pluginConfig?.AnalyticsEnabled || !JE.pluginConfig?.AnalyticsShareUsageCounts) return;
            api().ajax({
                type: 'POST',
                url: api().getUrl('/JellyfinEnhanced/usage/track'),
                data: JSON.stringify({ key }),
                contentType: 'application/json'
            }).catch(() => { /* best-effort; never surface analytics failures */ });
        } catch { /* best-effort */ }
    }

    // Expose helpers. Entries marked (core) are thin aliases over JE.core.*
    // kept for the frozen JE.helpers contract — new code should call core
    // directly.
    return {
        onViewPage: (...args: Parameters<SharedCore['navigation']['onViewPage']>) => JE.core.navigation.onViewPage(...args), // (core)
        onNavigate: (...args: Parameters<SharedCore['navigation']['onNavigate']>) => JE.core.navigation.onNavigate(...args), // (core)
        getItemCached,
        getCurrentView: () => JE.core.navigation.getCurrentView(), // (core)
        createObserver: (...args: Parameters<SharedCore['dom']['createObserver']>) => JE.core.dom.createObserver(...args), // (core)
        onBodyMutation: (...args: Parameters<SharedCore['dom']['onBodyMutation']>) => JE.core.dom.onBodyMutation(...args), // (core)
        removeBodySubscriber: (...args: Parameters<SharedCore['dom']['removeBodySubscriber']>) => JE.core.dom.removeBodySubscriber(...args), // (core)
        disconnectObserver: (...args: Parameters<SharedCore['dom']['disconnectObserver']>) => JE.core.dom.disconnectObserver(...args), // (core)
        disconnectAllObservers: () => JE.core.dom.disconnectAllObservers(), // (core)
        getHeaderRightContainer,
        getHeaderButtonTray,
        getSidebarContainer,
        onSidebarRebuilt,
        isActiveTabContainer,
        observeTabContainers,
        waitForElement: (...args: Parameters<SharedCore['dom']['waitForElement']>) => JE.core.dom.waitForElement(...args), // (core)
        waitForCondition,
        debounce,
        throttle,
        retry,
        isElementVisible,
        addCSS, // (core)
        removeCSS: (...args: Parameters<SharedCore['ui']['removeCss']>) => JE.core.ui.removeCss(...args), // (core)
        escHtml: (...args: Parameters<SharedCore['ui']['escapeHtml']>) => JE.core.ui.escapeHtml(...args), // (core)
        createExternalLink,
        getExternalLinkIconSize,
        getHeaderElement,
        getHeaderBottom,
        isSafeAvatarUrl,
        resolveProtectedAvatarUrl,
        hydrateAvatarImages,
        clearAvatarObjectUrlCache,
        trackUsage,
        getHandlerCount: () => JE.core.navigation.getViewHandlerCount(), // (core)
        getObserverCount: () => JE.core.dom.getObserverCount(), // (core)
        getBodySubscriberCount: () => JE.core.dom.getBodySubscriberCount(), // (core)
        isAdmin
    };

    console.log('🪼 Jellyfin Enhanced: Helpers initialized successfully');


}
